SELECT CASE WHEN s.risk_reward_ratio < 0.5 THEN 'a_<0.5' WHEN s.risk_reward_ratio < 1 THEN 'b_0.5-1' WHEN s.risk_reward_ratio < 1.5 THEN 'c_1-1.5' ELSE 'd_>=1.5' END AS rr_bucket, p.close_reason, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, SUM(p.realized_pnl < 0) AS losses, ROUND(SUM(p.realized_pnl), 6) AS total_pnl, ROUND(AVG((p.take_profit - p.entry_price) / p.entry_price * 100), 4) AS avg_final_tp_pct FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at IS NOT NULL GROUP BY rr_bucket, p.close_reason ORDER BY rr_bucket, n DESC LIMIT 60